function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3200);}
function parentElement(node){return node?.nodeType===1?node:node?.parentElement;}
function eligible(range){if(!range||!editor.contains(range.startContainer)||!editor.contains(range.endContainer))return false;return !parentElement(range.startContainer)?.closest('figcaption')&&!parentElement(range.endContainer)?.closest('figcaption');}
