function menuItem(action,label,icon=icons[action],suffix=''){return `<button class="menu-item" data-choice="${action}">${icon?img(icon):''}<span>${label}</span>${suffix?`<small>${suffix}</small>`:''}</button>`;}
function state(){const copy=editor.cloneNode(true);copy.querySelectorAll('.drag-source,.anchor-flash').forEach(n=>n.classList.remove('drag-source','anchor-flash'));return {html:copy.innerHTML,title:title.innerText,comments:structuredClone(comments)};}
function pushHistory(){clearTimeout(historyTimer);const next=state();if(historyIndex>=0&&JSON.stringify(history[historyIndex])===JSON.stringify(next))return;history=history.slice(0,historyIndex+1);history.push(next);if(history.length>80)history.shift();historyIndex=history.length-1;updateUndo();}
function updateUndo(){$('[data-action="undo"]').disabled=historyIndex<=0;$('[data-action="redo"]').disabled=historyIndex>=history.length-1;}
function applyState(s){editor.innerHTML=s.html;upgradeAttachments();upgradeBlockControls();upgradeAccordions();title.textContent=s.title;comments=structuredClone(s.comments||{});savedRange=null;selectedMedia=null;closeSelection();updateEmpty();save();updateUndo();}
function undo(){clearTimeout(historyTimer);pushHistory();if(historyIndex>0){historyIndex--;applyState(history[historyIndex]);}}
function redo(){clearTimeout(historyTimer);if(historyIndex<history.length-1){historyIndex++;applyState(history[historyIndex]);}}
