function save(){if(!loaded)return;clearTimeout(saveTimer);$('#save-status').textContent='Сохранение…';saveTimer=setTimeout(()=>{if(!db){$('#save-status').textContent='Не удалось сохранить в браузере';return;}try{const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put(state(),'current');tx.oncomplete=()=>$('#save-status').textContent='Сохранено в этом браузере';tx.onerror=()=>$('#save-status').textContent='Не удалось сохранить в браузере';}catch{$('#save-status').textContent='Не удалось сохранить в браузере';}},450);}
async function load(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('cu-longread-prototype',1);req.onupgradeneeded=()=>req.result.createObjectStore('draft');req.onsuccess=()=>resolve(req.result);req.onerror=reject;});const draft=await new Promise(resolve=>{const req=db.transaction('draft').objectStore('draft').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);});if(draft){editor.innerHTML=draft.html;title.textContent=draft.title;comments=draft.comments||{};}}catch{}upgradeAttachments();upgradeBlockControls();upgradeAccordions();loaded=true;updateEmpty();pushHistory();}
function closeSelection(){bubble.hidden=true;hidePopup();}
