function updateActive(){updateFormatLabel();for(const b of document.querySelectorAll('[data-action]')){const c={bold:'bold',italic:'italic',underline:'underline',strike:'strikeThrough',sub:'subscript',sup:'superscript'}[b.dataset.action];if(c){const active=document.queryCommandState(c);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}}}
function topBlock(node){let el=parentElement(node);while(el&&el!==editor&&el.parentElement!==editor)el=el.parentElement;return el?.parentElement===editor?el:null;}
