dragHandle.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();hidePopup();bubble.hidden=true;const source=activeBlock?.isConnected?activeBlock:editor.firstElementChild;if(!source)return;remember();blockDrag={source,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,started:false,before:null,preview:null};dragHandle.setPointerCapture(e.pointerId);});
