function autoScrollBlocks(){if(!blockDrag?.started)return;const y=blockDrag.y,top=$('#toolbar').getBoundingClientRect().bottom+48;let speed=y<top?-Math.min(18,(top-y)/4):y>innerHeight-60?Math.min(18,(y-innerHeight+60)/4):0;if(speed)window.scrollBy(0,speed);dragTarget();dragFrame=requestAnimationFrame(autoScrollBlocks);}
function startBlockDrag(){const d=blockDrag;if(!d||d.started)return;pushHistory();d.started=true;d.source.classList.add('drag-source');document.body.classList.add('reordering');d.preview=document.createElement('div');d.preview.className='drag-preview';d.preview.textContent=d.source.querySelector('img')?'Изображение':d.source.classList.contains('columns')?'Текст в две колонки':d.source.classList.contains('info')?'Информационный блок':d.source.textContent.trim().slice(0,70)||'Пустой блок';document.body.append(d.preview);autoScrollBlocks();}
