dragHandle.addEventListener('pointermove',e=>{if(!blockDrag)return;blockDrag.x=e.clientX;blockDrag.y=e.clientY;if(Math.hypot(e.clientX-blockDrag.startX,e.clientY-blockDrag.startY)>4)startBlockDrag();dragTarget();});
