function blockIconButton(action){const label=action==='delete'?'Удалить блок':'Цвет фона';return `<button class="icon-button" data-block-action="${action}" aria-label="${label}" title="${label}"><img src="assets/${action==='delete'?'trash.svg':'c7677.svg'}" alt=""></button>`;}
