function accordionHTML(heading='',body='',open=true){return `<details class="block accordion" contenteditable="false" ${open?'open':''}><summary class="accordion-header"><div class="accordion-title${heading?'':' is-empty'}" contenteditable="true" role="textbox" aria-label="Заголовок аккордеона" data-placeholder="Заголовок...">${heading}</div><div class="accordion-actions" contenteditable="false"><button class="accordion-icon" data-accordion-action="delete" aria-label="Удалить аккордеон" title="Удалить аккордеон"><img src="assets/accordion-close.svg" width="20" height="20" alt=""></button><button class="accordion-icon" data-accordion-action="toggle" aria-label="${open?'Свернуть':'Развернуть'} аккордеон" aria-expanded="${open}" title="${open?'Свернуть':'Развернуть'} аккордеон"><img src="assets/accordion-chevron.svg" width="20" height="20" alt=""></button></div></summary><div class="accordion-body${body?'':' is-empty'}" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Текст аккордеона" data-placeholder="Текст...">${body||'<p><br></p>'}</div></details>`;}
function upgradeAccordions(){editor.querySelectorAll('.accordion-title').forEach(n=>n.setAttribute('contenteditable','true'));for(const old of editor.querySelectorAll('details:not(.accordion)')){const heading=old.querySelector('summary')?.textContent.trim()||'',body=old.cloneNode(true);body.querySelector('summary')?.remove();const text=body.textContent.trim(),t=document.createElement('template');t.innerHTML=accordionHTML(heading==='Заголовок аккордеона'?'':esc(heading),text==='Текст аккордеона'?'':body.innerHTML,old.open);old.replaceWith(t.content);}}
