function imageHTML(src,alt=''){return `<figure class="block media" contenteditable="false" style="width:648px">${blockControls()}<div class="image-box"><img src="${esc(src)}" alt="${esc(alt)}" draggable="false"><button class="resize-handle left" data-resize="left" tabindex="0" aria-label="Изменить ширину изображения слева"></button><button class="resize-handle right" data-resize="right" tabindex="0" aria-label="Изменить ширину изображения справа"></button></div><figcaption contenteditable="plaintext-only" role="textbox" aria-label="Описание изображения"></figcaption></figure>`;}
