function colors(anchor,mode,block=null){const palette=mode==='color'?['#1c1c1e','#5a5e62','#8a8e93','#d53d3d','#bd6a18','#348158','#2b74bd','#7460ce','#a9408e','#ffffff','#000000','#a3965c']:['#ffffff','#f0f1f3','#e9e5ff','#dfeeff','#e2f4e7','#fff2cc','#ffe6dd','#fce0ef','#ddd5ff','#c6ebf0','#e7f0c5','#d6d6d6'];showPopup(`<div class="menu-title">${block?'Цвет фона инфоблока':mode==='color'?'Цвет текста':'Цвет фона текста'}</div><div class="swatches">${palette.map(c=>`<button class="swatch" data-color="${c}" style="background:${c}" title="${c}" aria-label="Цвет ${c}"></button>`).join('')}</div><label class="custom-color">Другой цвет <input type="color" id="custom-color" value="${palette[0]}"></label><button class="menu-item" data-color="reset">Сбросить цвет</button>`,anchor,240,'color');popup.colorMode=mode;popup.targetBlock=block;}
function applyColor(c){if(popup.targetBlock){pushHistory();popup.targetBlock.style.backgroundColor=c==='reset'?'#e9e5ff':c;changed();}else command(popup.colorMode==='color'?'foreColor':'hiliteColor',c==='reset'?(popup.colorMode==='color'?'#1c1c1e':'transparent'):c);hidePopup();}
