$('#more').addEventListener('click',()=>{if(menuKind==='settings'){hidePopup();return;}showPopup('<div class="menu-title">Начальный сценарий</div>'+menuItem('scenario:empty','Новая страница','bbf44')+menuItem('scenario:content','Страница с контентом','9339c')+menuItem('scenario:info','Информационный блок','badec')+menuItem('scenario:columns','Текст в две колонки','39370')+'<div class="menu-title">Прототип</div>'+menuItem('threads','Комментарии','ef127')+menuItem('pdf','Скачать PDF','25dc1')+menuItem('export','Скачать черновик','25dc1')+menuItem('import','Открыть черновик','25dc1')+'<div class="empty-note">Смена сценария заменит текст. Действие можно отменить. Черновик и комментарии сохраняются в этом браузере.</div>',$('#more'),300,'settings');});
const intro='После релиза дизайнеры продолжают сопровождение и развитие продукта. Совокупность всех процессов именуется продукт-ревью. Его цель — повышение качества продуктов, соответствие ожиданиям пользователей, улучшение показателей (там, где это возможно)';
const outro='Как это делается: внутренняя обратная связь: на встречах, через каналы связи, фиксируются отзывы в письменном виде. Внешняя обратная связь: через команду техподдержки, а также через формы отзывов собирается информация от пользователей. В дальнейшем планируется более тесное взаимодействие с пользователями, когда будут настроены процессы привлечения их к исследованию продуктов';
const steps='<h2>Этапы</h2><ol><li>Что это: генерация идей для развития продукта, предложения как по точечным улучшениям, так и стратегическое планирование. Процесс, сопровождающий продукт на всем его жизненном цикле.</li><li>Зачем это нужно: позволяет улучшать продукт, делать его более ценным для пользователя, и приносить прибыль компании</li><li>Как это делается: без привязки к релизам. Идеи могут как озвучиваться на блейнштормах, так и просто предлагаться сотрудниками в любой момент (на личной встрече, в переписке, в формате задач на улучшения и т.п.)</li><li>Стейкхолдеры этапа: весь дизайн-отдел, менеджер продукта, любой сотрудник компании</li></ol>';
function setScenario(kind){pushHistory();comments={};savedRange=null;title.textContent=kind==='empty'?'':'1.2 Роль бэкенда в веб-разработке';editor.innerHTML=kind==='empty'?'<p><br></p>':kind==='info'?steps+infoHTML('<p>'+intro+'</p>')+'<p>'+outro+'</p>':kind==='columns'?columnsHTML('<p>'+intro+'</p>','<p>Для того, чтобы не плодить массу файлов, которые будут содержать 1-2 таска, обсуждаем с менеджерами масштабность эпиков при их создании. Вариант: при появлении эпиков с названиями «Доработки/Изменения/Адаптация etc» продолжаем наполнять файл с основным дизайном того, что упоминается.</p>')+steps+'<p>'+outro+'</p>':'<p>'+intro+'</p>'+steps+imageHTML('assets/56150.png','Горная долина')+'<p>'+outro+'</p>';blockTools.style.top='0px';activeBlock=null;selectMedia(null);changed();window.scrollTo(0,0);}
function exportDraft(){const blob=new Blob([JSON.stringify({version:1,...state()})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='longread-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);hidePopup();}
// Print a separate snapshot so expanding accordions never changes the draft.
async function exportPDF(){
 if(exportPDF.busy)return;
 exportPDF.busy=true;hidePopup();bubble.hidden=true;
 let frame;
 try{
  const copy=editor.cloneNode(true);
  copy.className='';
  copy.querySelectorAll('.block-controls,.accordion-actions,.resize-handle,.anchor-point,button').forEach(n=>n.remove());
  copy.querySelectorAll('[contenteditable]').forEach(n=>n.removeAttribute('contenteditable'));copy.removeAttribute('contenteditable');
  copy.querySelectorAll('.selected,.is-empty,.drag-source,.anchor-flash').forEach(n=>n.classList.remove('selected','is-empty','drag-source','anchor-flash'));
  copy.querySelectorAll('details').forEach(n=>n.open=true);
  copy.querySelectorAll('video,audio').forEach(n=>{const note=document.createElement('p');note.className='pdf-media-note';note.textContent=n.tagName==='VIDEO'?'Видео (доступно в редакторе)':'Аудио (доступно в редакторе)';n.replaceWith(note);});
  copy.querySelectorAll('a[download]').forEach(n=>n.removeAttribute('href'));
  const heading=title.innerText.trim(),filename=heading||'Новая страница';
  frame=document.createElement('iframe');frame.title='Печатная версия страницы';frame.setAttribute('aria-hidden','true');
  frame.style.cssText='position:fixed;left:-20000px;top:0;width:1050px;height:800px;border:0;pointer-events:none';
  const ready=new Promise((resolve,reject)=>{frame.onload=resolve;frame.onerror=()=>reject(Error('print load'));});
  frame.srcdoc=`<!doctype html><html lang="ru"><head><meta charset="utf-8"><base href="${esc(document.baseURI)}"><title>${esc(filename)}</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="pdf.css"></head><body class="pdf-page"><main>${heading?`<h1>${esc(heading)}</h1>`:''}${copy.outerHTML}</main></body></html>`;
  document.body.append(frame);await ready;
  const doc=frame.contentDocument;
  await doc.fonts.ready;
  await Promise.all([...doc.images].map(n=>n.decode().catch(()=>{})));
  await new Promise(resolve=>frame.contentWindow.requestAnimationFrame(()=>frame.contentWindow.requestAnimationFrame(resolve)));
  frame.contentWindow.addEventListener('afterprint',()=>{frame.remove();exportPDF.busy=false;},{once:true});
  frame.contentWindow.focus();frame.contentWindow.print();
  // Keep the snapshot alive while the native print preview is open.
  setTimeout(()=>{frame.remove();exportPDF.busy=false;},300000);
 }catch{frame?.remove();exportPDF.busy=false;toast('Не удалось подготовить PDF. Попробуйте ещё раз.');}
}
function sanitizeHTML(html){const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('script,style,iframe,object,embed,link,meta,form,input,textarea').forEach(e=>e.remove());template.content.querySelectorAll('*').forEach(e=>{for(const a of [...e.attributes]){if(a.name.startsWith('on')||a.name==='srcdoc'||(['href','src'].includes(a.name)&&!(a.name==='href'&&e.tagName==='A'&&e.hasAttribute('download')&&a.value.startsWith('data:'))&&!(/^(https?:|mailto:|tel:|#|assets\/|data:image\/|data:audio\/|data:video\/)/i.test(a.value))))e.removeAttribute(a.name);}});return template.innerHTML;}
function uploadDraft(){hidePopup();const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const s=JSON.parse(await input.files[0].text());if(typeof s.html!=='string'||typeof s.title!=='string')throw Error();pushHistory();s.html=sanitizeHTML(s.html);const safe={};for(const [id,t]of Object.entries(s.comments||{})){if(!/^c[a-z0-9]+$/.test(id)||!Array.isArray(t.messages))continue;safe[id]={quote:String(t.quote||''),messages:t.messages.map(m=>({author:String(m.author||'Редактор'),authorId:String(m.authorId||''),text:String(m.text||''),at:Number(m.at)||Date.now()}))};}s.comments=safe;applyState(s);pushHistory();toast('Черновик открыт');}catch{toast('Не удалось открыть черновик. Выберите JSON-файл, скачанный из редактора.');}};input.click();}
document.execCommand('defaultParagraphSeparator',false,'p');load();
